"""FAISS semantic-search wrapper. LangChain-free — direct faiss-cpu API."""

from __future__ import annotations

from pathlib import Path

import faiss
import numpy as np
from ovgenai_retrieval.embedder import Embedder


class SemanticSearcher:
    """Wraps a FAISS flat/HNSW/IVF index plus an embedder for the query side."""

    def __init__(
        self,
        faiss_path: str | Path,
        embedder: Embedder,
        expected_dimension: int | None = None,
        expected_count: int | None = None,
    ):
        self._index = faiss.read_index(str(faiss_path))
        self._embedder = embedder
        if expected_dimension is not None and self.dimension != expected_dimension:
            raise ValueError(
                f"FAISS dimension mismatch for {faiss_path}: index has "
                f"{self.dimension}, manifest declares {expected_dimension}. Reindex "
                "the bundle with the configured embedding model."
            )
        if expected_count is not None and self.ntotal != expected_count:
            raise ValueError(
                f"FAISS row count mismatch for {faiss_path}: index has {self.ntotal}, "
                f"docstore has {expected_count}. Rebuild the bundle."
            )

    @property
    def ntotal(self) -> int:
        return int(self._index.ntotal)

    @property
    def dimension(self) -> int:
        return int(self._index.d)

    def top_k(self, query: str, k: int = 10) -> list[tuple[int, float]]:
        """Return ``[(faiss_row_idx, similarity_score), ...]`` sorted desc.

        NVIDIA retrieval embeddings are L2-normalized by convention. We return
        inner products directly and negate L2 distances so larger scores are
        always better.
        """
        if self.ntotal == 0 or k <= 0:
            return []
        vec = np.asarray([self._embedder.embed_query(query)], dtype=np.float32)
        if vec.ndim != 2 or vec.shape[1] != self.dimension:
            actual = vec.shape[1] if vec.ndim == 2 else tuple(vec.shape)
            raise ValueError(
                f"Query embedding dimension mismatch: embedder returned {actual}, "
                f"but the FAISS index requires {self.dimension}. Reindex the bundle "
                "or configure the embedding model recorded in its manifest."
            )
        # LangChain's FAISS store uses L2 distance by default for flat indexes;
        # rag-prep builds with that default. Convert L2 -> similarity via 1 - d/2
        # after assuming unit-norm vectors. We detect by metric type on the index.
        distances, indices = self._index.search(vec, min(k, self.ntotal))
        out: list[tuple[int, float]] = []
        metric = getattr(self._index, "metric_type", faiss.METRIC_L2)
        for d, idx in zip(distances[0], indices[0]):
            if idx < 0:
                continue
            if metric == faiss.METRIC_INNER_PRODUCT:
                score = float(d)
            else:  # METRIC_L2: convert distance to similarity-ish score
                score = float(-d)  # higher = closer (more similar)
            out.append((int(idx), score))
        return out

"""Bundle — wraps a bundle directory: manifest + FAISS + docstore + optional BM25.

Three generations supported:

- **Legacy pickle** (today's MCP data): ``index.faiss`` + ``index.pkl``
- **Legacy JSON** (post-faiss-safe migration): ``index.faiss`` + ``index.json``
- **Manifest v1** (upgraded rag-prep and data_collection scripts):
  ``manifest.json`` + ``index.faiss`` + ``index.json`` + ``bm25.<backend>`` + ``files/``

``load_bundle(path)`` dispatches to the correct loader and returns a uniform
``Bundle`` instance.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any

from ovgenai_retrieval._compat import DocStore, DocStoreRecord, load_json_docstore, load_pickle_docstore
from ovgenai_retrieval.manifest import Manifest


@dataclass
class Bundle:
    """A loaded bundle. Consumers read ``manifest.bundle_type`` to dispatch."""

    path: Path
    manifest: Manifest
    docstore: DocStore | None = None
    """None for ``catalog`` bundles (they use :attr:`catalog_data` instead)."""
    catalog_data: Any = None
    """Raw JSON blob loaded from the catalog file, for ``bundle_type='catalog'``."""

    @property
    def type(self) -> str:
        return self.manifest.bundle_type

    @property
    def has_faiss(self) -> bool:
        return self.manifest.embeddings is not None and (self.path / self.manifest.embeddings.file).exists()

    @property
    def has_lexical_sidecar(self) -> bool:
        return self.manifest.lexical is not None and (self.path / self.manifest.lexical.file).exists()

    @property
    def faiss_index_path(self) -> Path:
        assert self.manifest.embeddings is not None, "bundle has no embeddings"
        return self.path / self.manifest.embeddings.file

    def iter_records(self) -> list[DocStoreRecord]:
        """Convenience: returns all docstore records ordered by faiss row index."""
        assert self.docstore is not None, "bundle has no docstore"
        # Build index->record map; records are stored doc_id-keyed
        idx_to_record: dict[int, DocStoreRecord] = {}
        for rec in self.docstore.records:
            faiss_idx = self.docstore.id_to_faiss_index.get(rec.doc_id)
            if faiss_idx is not None:
                idx_to_record[faiss_idx] = rec
        expected_rows = list(range(len(self.docstore.records)))
        if sorted(idx_to_record) != expected_rows:
            raise ValueError(f"Bundle {self.path} has a non-contiguous or incomplete FAISS row map")
        if self.manifest.chunks is not None and self.manifest.chunks.count != len(expected_rows):
            raise ValueError(
                f"Bundle {self.path} manifest declares {self.manifest.chunks.count} chunks "
                f"but the docstore contains {len(expected_rows)}"
            )
        return [idx_to_record[i] for i in expected_rows]


def _load_catalog(bundle_dir: Path, manifest: Manifest) -> Any:
    if manifest.catalog is None:
        # Fallback: look for a single *.json that isn't index.json
        candidates = [p for p in bundle_dir.glob("*.json") if p.name not in {"index.json", "manifest.json"}]
        if len(candidates) == 1:
            return _read_json(candidates[0])
        raise ValueError(
            f"Catalog bundle at {bundle_dir} has no 'catalog' field in manifest "
            f"and no single catalog JSON could be auto-detected."
        )
    return _read_json(bundle_dir / manifest.catalog.file)


def _read_json(path: Path) -> Any:
    import json

    return json.loads(path.read_text(encoding="utf-8"))


def load_bundle(
    path: str | Path,
    *,
    allow_pickle: bool = False,
) -> Bundle:
    """Load a bundle from a directory.

    Args:
        path: Path to the bundle directory.
        allow_pickle: Must be True to load legacy pickle docstores. Default False.

    Returns:
        A :class:`Bundle` instance.
    """
    bundle_dir = Path(path)
    if not bundle_dir.is_dir():
        raise FileNotFoundError(f"Bundle directory not found: {bundle_dir}")

    manifest_file = bundle_dir / "manifest.json"
    if manifest_file.exists():
        manifest = Manifest.load(manifest_file)
    else:
        manifest = Manifest.synthesize_from_legacy(bundle_dir)

    # Catalog-shaped bundles skip docstore loading
    if manifest.bundle_type == "catalog":
        catalog_data = _load_catalog(bundle_dir, manifest)
        return Bundle(path=bundle_dir, manifest=manifest, catalog_data=catalog_data)

    docstore: DocStore | None = None
    if manifest.docstore is not None:
        docfile = bundle_dir / manifest.docstore.file
        if manifest.docstore.format == "json":
            docstore = load_json_docstore(docfile)
        elif manifest.docstore.format == "pickle":
            docstore = load_pickle_docstore(docfile, allow_pickle=allow_pickle)

    # Fallback for legacy bundles with no docstore field in synthesized manifest
    if docstore is None:
        if (bundle_dir / "index.json").exists():
            docstore = load_json_docstore(bundle_dir / "index.json")
        elif (bundle_dir / "index.pkl").exists():
            docstore = load_pickle_docstore(bundle_dir / "index.pkl", allow_pickle=allow_pickle)

    return Bundle(path=bundle_dir, manifest=manifest, docstore=docstore)

"""CatalogIndex — by-name / prefix / filter lookup for structured JSON bundles.

Examples of catalog corpora: ``extensions_database.json``, ``usd_atlas.json``,
``app_templates.json``, per-extension ``codeatlas/*.json``, ``api_docs/*.json``.

These do NOT want FAISS or BM25 over chunks. Consumers look up by exact name
or prefix (e.g., ``get_kit_extension_details(name="omni.ui")``). Keeping them
outside HybridRetriever avoids forcing an artificial text-search interface onto
a by-name lookup.
"""

from __future__ import annotations

from collections.abc import Callable
from typing import Any

from ovgenai_retrieval.bundle import Bundle


class CatalogIndex:
    """Lookup over a structured JSON catalog bundle."""

    def __init__(self, bundle: Bundle, *, key_field: str | None = None):
        if bundle.type != "catalog":
            raise TypeError(f"CatalogIndex requires bundle_type='catalog', got {bundle.type!r}")
        data = bundle.catalog_data
        self._bundle = bundle
        self._key_field = key_field or (bundle.manifest.catalog.key_field if bundle.manifest.catalog else "name")

        # The catalog can be either a dict (name -> entry) or a list of entries.
        if isinstance(data, dict):
            self._by_name: dict[str, Any] = dict(data)
            self._all: list[Any] = list(data.values())
        elif isinstance(data, list):
            self._by_name = {}
            self._all = list(data)
            for entry in data:
                k = entry.get(self._key_field)
                if k is not None:
                    self._by_name[str(k)] = entry
        else:
            raise TypeError(f"Unsupported catalog shape: {type(data).__name__}")

    # ------------------------------------------------------------------

    @property
    def size(self) -> int:
        return len(self._all)

    def get_by_name(self, name: str) -> Any | None:
        return self._by_name.get(name)

    def prefix_search(self, prefix: str, limit: int | None = None) -> list[Any]:
        out: list[Any] = []
        for name, entry in self._by_name.items():
            if name.startswith(prefix):
                out.append(entry)
                if limit is not None and len(out) >= limit:
                    break
        return out

    def filter(self, predicate: Callable[[Any], bool]) -> list[Any]:
        return [e for e in self._all if predicate(e)]

    def all(self) -> list[Any]:
        return list(self._all)

